import os, json, numpy as np

N = 26
SAFETY = 1e-9

P_C = 'storage/noesis/latest_centers.txt'
P_R = 'storage/noesis/latest_radii.txt'
P_SUM_SOTA = 'storage/noesis/exports/sota_243/summary_tol1e8.json'
P_SUM_FALL = 'storage/noesis/exports/summary_tol1e8.json'
P_GATE_SLACK = 'storage/noesis/exports/operator_gate_dual_tol_latest.json'
P_GATE_KKT   = 'storage/noesis/exports/operator_gate_dual_tol_kkt_latest.json'
P_TAN_V1     = 'storage/noesis/exports/tangent_step_attempt_v1.json'
P_TAN_V2     = 'storage/noesis/exports/tangent_step_attempt_v2.json'
OUT_JSON     = 'storage/noesis/exports/paper_tables.json'

def load_json(path):
    if os.path.exists(path):
        try:
            with open(path, 'r') as f:
                return json.load(f)
        except Exception:
            return None
    return None

def load_snapshot():
    c = np.loadtxt(P_C, dtype=float).reshape(N,2)
    r = np.loadtxt(P_R, dtype=float).reshape(N,)
    return c, r

def construct_packing():
    c, r = load_snapshot()

    # Collect SOTA summary, prefer sota_243 path
    s_sota = load_json(P_SUM_SOTA) or load_json(P_SUM_FALL) or {}
    degree_hist = s_sota.get('degree_histogram', {})
    sota_entry = {
        'sum_radii': s_sota.get('sum_radii', float(np.sum(r))),
        'active_boundary_count': s_sota.get('active_boundary_count', s_sota.get('boundary_count')),
        'active_pair_count': s_sota.get('active_pair_count', s_sota.get('pair_count')),
        'degree_histogram': degree_hist
    }

    gate_slack = load_json(P_GATE_SLACK) or {}
    gate_kkt   = load_json(P_GATE_KKT) or {}
    tan_v1     = load_json(P_TAN_V1) or {}
    tan_v2     = load_json(P_TAN_V2) or {}

    out = {
        'sota_243': sota_entry,
        'gate_slack_dual_tol': {
            'tols': gate_slack.get('policy', {}).get('tols'),
            'K_map': gate_slack.get('policy', {}).get('K_map'),
            'has_candidate': gate_slack.get('has_candidate'),
            'common_pairs_count': gate_slack.get('common_pairs_count'),
        },
        'gate_kkt_dual_tol': {
            'tols': gate_kkt.get('policy', {}).get('tols'),
            'K_map': gate_kkt.get('policy', {}).get('K_map'),
            'has_candidate': gate_kkt.get('has_candidate'),
            'common_pairs_count': gate_kkt.get('common_pairs_count'),
        },
        'tangent_attempts': [
            {'version':'v1',
             'status': 'trust_region_failed' if 'trust_region_failed' in str(tan_v1.get('error','')) else tan_v1.get('error'),
             'last_tau': tan_v1.get('last_tau'),
             'hinges': tan_v1.get('hinges')
            },
            {'version':'v2',
             'status': 'trust_region_failed' if 'trust_region_failed' in str(tan_v2.get('error','')) else tan_v2.get('error'),
             'last_tau': tan_v2.get('last_tau'),
             'hinges': tan_v2.get('hinges')
            }
        ]
    }

    os.makedirs(os.path.dirname(OUT_JSON), exist_ok=True)
    try:
        with open(OUT_JSON, 'w') as f:
            json.dump(out, f, indent=2)
    except Exception:
        pass

    # Return SOTA snapshot with tiny shrink
    return c.astype(float), np.maximum(r - SAFETY, 1e-6).astype(float)
